    16  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    17    if (!size) {
    18      // Hermes can't handle empty input, and it would have a performance cost
    19      // to do so.
    20      return 0;
    21    }
    22    // Hermes bytecode is assumed to be trusted, and there are often no checks
    23    // for validity (for performance purposes).
    24    // Discard inputs that would be interpreted as bytecode to avoid reporting
    25    // those as errors.
    26    if (HermesRuntime::isHermesBytecode(data, size)) {
    27      return 0;
    28    }
    29
    30    std::string s(reinterpret_cast<const char *>(data), size);
    31    s.append("\0");
    32    auto runtime = makeHermesRuntime();
    33    // Cap the run-time of the code so that fuzzing can stay efficient.
    34    constexpr uint32_t kTimeoutForRunningInMs = 10000;
    35    runtime->watchTimeLimit(kTimeoutForRunningInMs);
    36
    37    try {
    38      runtime->evaluateJavaScript(std::make_unique<StringBuffer>(s), "");
    39    } catch (const JSIException &e) {
    40      // Swallow JS-based exceptions.
    41      // The fuzzer will generate a lot of invalid JS, and if this causes an
    42      // exception to be thrown evaluating it, that's alright.
    43      // The fuzzer is more interested in inputs that cause the sort of crash that
    44      // doesn't throw an exception.
    45    }
    46    // Other types of exceptions are not ok to occur, and should be reported as
    47    // bugs.
    48    // Hermes throws no exceptions during normal operation, with the exception of
    49    // any that escape JS.
    50    return 0;
    51  }
